//! The shell icon set (BRL-0157): one original family generated by
//! `asset_src/player-shell/icons/build_icons.py`, which owns geometry, style and provenance.

/// Square navigation, action and Map Maker pictograms (128 px).
#[cfg(any(test, feature = "automation"))]
pub(crate) const PICTOGRAMS: [&str; 26] = [
    "chevron-left",
    "chevron-right",
    "chevron-up",
    "chevron-down",
    "lightning",
    "crosshair",
    "menu",
    "player",
    "arena",
    "skull",
    "edit",
    "trash",
    "empty",
    "close",
    "check",
    "warning",
    "play",
    "place",
    "select",
    "erase",
    "grid",
    "symmetry",
    "fit",
    "search",
    "rotate",
    "duplicate",
];

/// Ultimate and passive family badges on the shared hexagon emblem (240x200 px).
#[cfg(any(test, feature = "automation"))]
pub(crate) const BADGES: [&str; 16] = [
    "dash", "sentry", "cloak", "scan", "field", "blast", "cold", "fire", "poison", "heal", "blob",
    "feather", "shield", "pulse", "target", "cycle",
];

/// Weapon part family illustrations (288x240 px).
#[cfg(any(test, feature = "automation"))]
pub(crate) const PARTS: [&str; 5] = [
    "part-magazine",
    "part-ammunition",
    "part-barrel",
    "part-chamber",
    "part-element",
];

/// Hanging mode pennants (250x310 px), in `AdvertisedRulesSummary` order: Takedown, Turf Hold,
/// Vault Break, Zombie (BRL-1wms), Shard Rush (BRL-wrer). Names are `mode-<mode key>`.
pub(crate) const MODE_PENNANTS: [&str; 5] = [
    "mode-takedown",
    "mode-turf-hold",
    "mode-vault-break",
    "mode-zombie",
    "mode-shard-rush",
];

/// The badge of an ultimate family. Icons are selected by advertised semantic family, never by
/// built-in definition IDs; the brawler screens and the in-match ultimate button share it.
pub(crate) fn ultimate_icon(kind: brawler::builds::UltimateKind) -> &'static str {
    use brawler::builds::UltimateKind;
    match kind {
        UltimateKind::Dash => "dash",
        UltimateKind::Sentry => "sentry",
        UltimateKind::SelfCloak => "cloak",
        UltimateKind::RevealScan => "scan",
        UltimateKind::ConcealmentField => "field",
        UltimateKind::DemolitionStrike => "blast",
        UltimateKind::CryogenicField => "cold",
        UltimateKind::FireField => "fire",
        UltimateKind::PoisonField => "poison",
        UltimateKind::RestorationField => "heal",
        UltimateKind::BigBlob => "blob",
    }
}

/// Asset path of a named icon.
pub(crate) fn path(name: &str) -> String {
    format!("brawler/ui/icons/{name}.png")
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;
    use std::path::Path;

    fn all() -> impl Iterator<Item = &'static str> {
        PICTOGRAMS
            .into_iter()
            .chain(BADGES)
            .chain(PARTS)
            .chain(MODE_PENNANTS)
    }

    fn png_size(bytes: &[u8]) -> (u32, u32) {
        assert_eq!(&bytes[..8], b"\x89PNG\r\n\x1a\n");
        assert_eq!(&bytes[12..16], b"IHDR");
        assert_eq!(bytes[25], 6, "icons keep RGBA alpha");
        (
            u32::from_be_bytes(bytes[16..20].try_into().unwrap()),
            u32::from_be_bytes(bytes[20..24].try_into().unwrap()),
        )
    }

    #[test]
    fn every_icon_is_a_generated_rgba_png_with_an_svg_source() {
        let root = Path::new(crate::REPOSITORY_ROOT);
        let generator =
            std::fs::read_to_string(root.join("asset_src/player-shell/icons/build_icons.py"))
                .unwrap();
        let classes = [
            (&PICTOGRAMS[..], (128, 128)),
            (&BADGES[..], (240, 200)),
            (&PARTS[..], (288, 240)),
            (&MODE_PENNANTS[..], (250, 310)),
        ];
        for (name, expected) in classes
            .into_iter()
            .flat_map(|(names, size)| names.iter().map(move |name| (*name, size)))
        {
            let bytes = std::fs::read(root.join("assets").join(path(name)))
                .unwrap_or_else(|_| panic!("missing icon {name}"));
            assert_eq!(png_size(&bytes), expected, "{name} size");
            assert!(
                generator.contains(&format!("\"{name}\": (")),
                "{name} is not defined by the generator"
            );
            assert!(
                root.join(format!("asset_src/player-shell/icons/svg/{name}.svg"))
                    .is_file(),
                "{name} has no editable SVG source"
            );
        }
    }

    #[test]
    fn every_registered_mode_key_names_its_pennant_in_dashboard_order() {
        use bevy::prelude::*;
        let mut app = App::new();
        app.add_plugins((
            brawler::modes::ModeRegistryPlugin,
            brawler::modes::BuiltInModeRegistrationsPlugin,
        ));
        brawler::test_app::finalize(&mut app);
        let modes = app.world().resource::<brawler::modes::ModeRegistry>();
        for (pennant, definition) in MODE_PENNANTS.into_iter().zip([
            brawler::map::TAKEDOWN_MODE_DEFINITION,
            brawler::map::TURF_HOLD_MODE_DEFINITION,
            brawler::map::VAULT_BREAK_MODE_DEFINITION,
            brawler::map::ZOMBIE_MODE_DEFINITION,
            brawler::map::SHARD_RUSH_MODE_DEFINITION,
        ]) {
            let key = modes
                .descriptor_for_definition(definition)
                .expect("built-in mode is registered")
                .key;
            assert_eq!(pennant, format!("mode-{key}"));
        }
    }

    #[test]
    fn icon_directory_holds_exactly_the_set_and_retired_icons_are_gone() {
        let root = Path::new(crate::REPOSITORY_ROOT);
        let shipped: BTreeSet<String> = std::fs::read_dir(root.join("assets/brawler/ui/icons"))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        let expected: BTreeSet<String> = all().map(|name| format!("{name}.png")).collect();
        assert_eq!(shipped, expected);
        assert!(!root.join("assets/brawler/ui/details").exists());
        assert!(!root.join("assets/licenses/kenney-game-icons.txt").exists());
        for retired in [
            "icon-skull",
            "icon-chevron",
            "part-barrel",
            "takedown",
            "turf-hold",
            "vault-break",
            "zombie",
            "game-badge-turf-hold",
            "game-badge-vault-break",
            "game-badge-zombie",
        ] {
            assert!(
                !root
                    .join(format!("assets/brawler/ui/shell/{retired}.png"))
                    .exists()
            );
        }
        assert!(
            root.join("assets/licenses/pewpew-blitz-original-icons.txt")
                .is_file()
        );
    }

    fn client_sources(dir: &Path, text: &mut String) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                client_sources(&path, text);
            } else if path.extension().is_some_and(|ext| ext == "rs") {
                text.push_str(&std::fs::read_to_string(&path).unwrap());
            }
        }
    }

    /// BRL-4jdx: the shell directory ships only artwork a screen loads, either by a literal path
    /// in client source or as the overview of a map a game type offers in Practice.
    #[test]
    fn shell_directory_holds_only_loaded_artwork() {
        let root = Path::new(crate::REPOSITORY_ROOT);
        let mut source = String::new();
        client_sources(&root.join("packages/brawler-client/src"), &mut source);
        let game_types = std::fs::read_to_string(root.join("config/server/game-types.ron"))
            .expect("game types config");
        let practice_maps: BTreeSet<&str> = game_types
            .split("maps: [")
            .skip(1)
            .filter_map(|rest| rest.split(']').next())
            .flat_map(|list| list.split(',').map(|key| key.trim().trim_matches('"')))
            .filter(|key| !key.is_empty())
            .collect();
        assert!(!practice_maps.is_empty());
        assert!(source.contains("format!(\"brawler/ui/shell/{}-overview.png\", p.key)"));

        let shipped: BTreeSet<String> = std::fs::read_dir(root.join("assets/brawler/ui/shell"))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        for file in &shipped {
            let literal = source.contains(&format!("\"brawler/ui/shell/{file}\""));
            let overview = file
                .strip_suffix("-overview.png")
                .is_some_and(|key| practice_maps.contains(key));
            assert!(
                literal || overview,
                "no screen loads brawler/ui/shell/{file}"
            );
        }
        for key in practice_maps {
            assert!(
                shipped.contains(&format!("{key}-overview.png")),
                "Practice map {key} has no overview"
            );
        }
    }
}
